<script setup lang="ts">
const financialError=useFinancialError()
const { t } = useLanguage()
const db=useSupabase(),month=ref(nowMonth()),stats=ref<any>(null),error=ref(''),loading=ref(false)
async function load(){if(!db)return;loading.value=true;stats.value=null;error.value='';try{if(!isValidMonth(month.value))throw Error(t('financialUi.finance.monthInvalid'));const q=await db.rpc('monthly_registration_summary',{p_month:monthStart(month.value)});if(q.error)throw q.error;stats.value=q.data}catch(e){error.value=financialError(e)}finally{loading.value=false}}
onMounted(load)
</script>
<template><section><div class="table-toolbar"><label>{{ t('financialUi.registrationStats.title') }}<input v-model="month" type="month" @change="load"/></label><button class="btn" :disabled="loading" @click="load">{{ t('financialUi.registrationStats.refresh') }}</button></div><Notice :message="error" kind="error"/><p v-if="loading">{{ t('financialUi.loading') }}</p><template v-if="stats"><div class="kpi-grid"><div v-for="[key,label] in [['registrations',t('financialUi.registrationStats.registrations')],['unique_students',t('financialUi.registrationStats.uniqueStudents')],['active_classes',t('financialUi.registrationStats.activeClasses')],['active_teachers',t('financialUi.registrationStats.activeTeachers')]]" :key="key" class="card kpi"><div><small>{{label}}</small><strong>{{stats[key!]}}</strong></div></div></div><section class="card" style="margin-bottom:20px"><p>{{ t('financialUi.registrationStats.new',{newCount:stats.new_registrations,returningCount:stats.returning_registrations,legacyCount:stats.legacy_registrations}) }}</p><p class="hint">{{ t('financialUi.registrationStats.hint') }}</p><div class="grid-two"><div><h3>{{ t('financialUi.registrationStats.byClass') }}</h3><div v-for="c in stats.by_class" :key="c.class_id" class="summary-row"><span>{{c.class_name}}</span><strong>{{c.registrations}}</strong></div></div><div><h3>{{ t('financialUi.registrationStats.byTeacher') }}</h3><div v-for="t in stats.by_teacher" :key="t.teacher_id" class="summary-row"><span>{{t.teacher_name}}</span><strong>{{t.registrations}}</strong></div></div></div></section></template></section></template>
